    {
      "id": "first_result",
      "title": "Produce the first sourced result",
      "instructions": "Use actual authorized evidence to produce A launch action ledger with approved asset revisions, channel and owner, dates, dependency state, source receipts, first lead signals, and next review. A launch asset marked done in a project board is not proof it was published or sent; a form event is not a qualified lead or booked meeting. The fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the result and next action",
      "instructions": "Show source-linked facts, hypotheses, unknowns, exact proposed actions, owner, and approval boundaries. Record the owner decision."
    },
    {
      "id": "delivery",
      "title": "Choose publishing and delivery routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized CMS, campaign, CRM, and message actions. Read-only chat completes this decision. Do not publish assets, send outreach, enroll contacts, spend on ads, alter CRM stages, or claim pipeline lift without approved actions and observed provider and sales records."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed event or schedule with deduplication and cost rules. Manual-only completes this decision. Reconcile the same asset, campaign, event, and lead IDs; update only changed states, preserve approvals and receipts, and never issue duplicate distribution or lead follow-up."
    }
  ],
  "completed_steps": []
}

files.templates/revenue-operations-analyst/TEM:
{
  "schema_version": 1,
  "template_id": "revenue-operations-analyst",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm role and owner",
      "instructions": "Confirm whether Revenue Operations Analyst seeds this Crew or extends a compatible Crew. Preserve its existing identity and name the accountable GTM owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/revenue-operations-analyst/SKILL.md exists and revenue-operations-analyst is selected."
    },
    {
      "id": "scope",
      "title": "Bind one first job",
      "instructions": "Record exact product or offer, tenant, segment, period, policy version, source IDs, decision owner and exclusions. Minimum input: Period, campaign or offer, CRM stages, identity and attribution rules, authorized form and CRM exports and revenue-operations owner."
    },
    {
      "id": "access",
      "title": "Prove the source join",
      "instructions": "Read two form events, corresponding CRM lead revisions and one opportunity with campaign or source keys. Demonstrate a duplicate and an unmatched event, plus the approved lookback window. CRM, forms, analytics, ad or email provider and billing through scoped reads; exports work for the first reconciliation. Record permission and observed time; missing access stays blocked."
    },
    {
      "id": "policy",
      "title": "Verify the hard acceptance rule",
      "instructions": "Recompute unique leads and accepted opportunities, list join coverage and suppress unknown attribution. A form event, CRM lead and opportunity are different objects and must not be counted as the same outcome. Do not rewrite attribution, change CRM stages, merge identities, spend budget or claim generated revenue without reviewed source and owner approval."
    },
    {
      "id": "first_result",
      "title": "Produce a first sourced result",
      "instructions": "Use real authorized records to produce A source-linked GTM funnel reconciliation with deduplicated counts, stage definitions, join coverage, attribution limits and owner actions. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review with the accountable owner",
      "instructions": "Show source IDs, contrary evidence, uncertainty, rejected options and proposed next action; record the owner decision or correction."
    },
    {
      "id": "delivery",
      "title": "Choose the action route",
      "optional": true,
      "instructions": "Read-only chat completes this choice. Writes, publication, contact and money actions require separate exact-object approval and provider receipts. Do not rewrite attribution, change CRM stages, merge identities, spend budget or claim generated revenue without reviewed source and owner approval."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring work",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or event requires stable IDs, deduplication, cost and notification rules, reviewed by the owner. Reprocess the same event and CRM IDs idempotently, allow documented source lag and compare only like windows and stage rules."
    }
  ],
  "completed_steps": []
}

